CREATE TABLE IF NOT EXISTS public.prescription_audit_log (id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id),student_id uuid references public.alunos(id),workout_id uuid references public.treinos(id),actor_id uuid references auth.users(id),action text,version integer,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
ALTER TABLE public.prescription_audit_log ADD COLUMN IF NOT EXISTS organization_id uuid REFERENCES public.organizations(id); ALTER TABLE public.prescription_audit_log ADD COLUMN IF NOT EXISTS student_id uuid REFERENCES public.alunos(id); ALTER TABLE public.prescription_audit_log ADD COLUMN IF NOT EXISTS workout_id uuid REFERENCES public.treinos(id); ALTER TABLE public.prescription_audit_log ADD COLUMN IF NOT EXISTS actor_id uuid REFERENCES auth.users(id); ALTER TABLE public.prescription_audit_log ADD COLUMN IF NOT EXISTS action text; ALTER TABLE public.prescription_audit_log ADD COLUMN IF NOT EXISTS payload jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE TABLE IF NOT EXISTS public.user_access_audit (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),organization_id uuid references public.organizations(id),event_type text not null check(event_type in('login','logout','context_changed','admin_action','denied')),ip_hash text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
ALTER TABLE public.prescription_audit_log ENABLE ROW LEVEL SECURITY; ALTER TABLE public.user_access_audit ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS prescription_audit_read ON public.prescription_audit_log; DROP POLICY IF EXISTS access_audit_admin_read ON public.user_access_audit;
CREATE POLICY prescription_audit_read ON public.prescription_audit_log FOR SELECT TO authenticated USING(public.is_admin(auth.uid()) OR exists(select 1 from public.organization_members m where m.organization_id=prescription_audit_log.organization_id and m.user_id=auth.uid() and m.papel::text in('admin','manager','professor')));
CREATE POLICY access_audit_admin_read ON public.user_access_audit FOR SELECT TO authenticated USING(public.is_admin(auth.uid()));
DROP FUNCTION IF EXISTS public.record_user_access(text,uuid,jsonb);
CREATE OR REPLACE FUNCTION public.record_user_access(p_event_type text,p_organization_id uuid default null,p_metadata jsonb default '{}'::jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ begin if auth.uid() is null then return; end if; if p_event_type not in('login','logout','context_changed','admin_action','denied') then raise exception 'Evento inválido'; end if; if p_organization_id is not null and not(public.is_admin(auth.uid()) or exists(select 1 from public.organization_members m where m.organization_id=p_organization_id and m.user_id=auth.uid())) then raise exception 'Sem acesso à organização'; end if; insert into public.user_access_audit(user_id,organization_id,event_type,metadata) values(auth.uid(),p_organization_id,p_event_type,coalesce(p_metadata,'{}'::jsonb)); end $$;
CREATE OR REPLACE FUNCTION public.audit_workout_prescription() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ declare v_org uuid; v_action text; begin v_org:=coalesce(new.organization_id,old.organization_id); v_action:=case tg_op when 'INSERT' then 'created' when 'DELETE' then 'archived' when new.status='publicado' and old.status is distinct from new.status then 'published' else 'updated' end; insert into public.prescription_audit_log(organization_id,student_id,workout_id,actor_id,action,payload) values(v_org,coalesce(new.aluno_id,old.aluno_id),coalesce(new.id,old.id),auth.uid(),v_action,jsonb_build_object('status',coalesce(new.status,old.status),'name',coalesce(new.nome,old.nome))); return coalesce(new,old); end $$;
DROP TRIGGER IF EXISTS audit_workout_prescription ON public.treinos; CREATE TRIGGER audit_workout_prescription AFTER INSERT OR UPDATE OR DELETE ON public.treinos FOR EACH ROW EXECUTE FUNCTION public.audit_workout_prescription();
REVOKE ALL ON FUNCTION public.record_user_access(text,uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.record_user_access(text,uuid,jsonb) TO authenticated;

